#!/usr/bin/env bash
set -euo pipefail

# Test the compiler's emitted AES primitives against FIPS 197 on all targets.
# check.c is a conformance driver; every hardware operation comes from the
# LLVM object generated by TestAESMachineCode, without a C AES implementation.
repo_root=$(cd "$(dirname "$0")/.." && pwd)
artifact_dir=${1:?usage: test_aes_llvm.sh ARTIFACT_DIR}
mkdir -p "$artifact_dir"
artifact_dir=$(cd "$artifact_dir" && pwd)
cd "$repo_root"
LLGO_AES_CROSS_DIR="$artifact_dir" go test ./ssa -run '^TestAESMachineCode$' -count=1

for arch in amd64 386 arm64 arm ppc64 ppc64le riscv64; do
  flags=()
  case "$arch" in
    amd64) cc=x86_64-linux-gnu-gcc; emulator=qemu-x86_64; cpu=max; prekey=0 ;;
    386) cc=i686-linux-gnu-gcc; emulator=qemu-i386; cpu=max; prekey=0 ;;
    arm64) cc=aarch64-linux-gnu-gcc; emulator=qemu-aarch64; cpu=max; prekey=1 ;;
    arm) cc=arm-linux-gnueabihf-gcc; emulator=qemu-arm; cpu=max; prekey=1 ;;
    ppc64) cc=powerpc64-linux-gnu-gcc; emulator=qemu-ppc64; cpu=power8; prekey=0; flags=(-mcpu=power8) ;;
    ppc64le) cc=powerpc64le-linux-gnu-gcc; emulator=qemu-ppc64le; cpu=power8; prekey=0; flags=(-mcpu=power8) ;;
    riscv64) cc=riscv64-linux-gnu-gcc; emulator=qemu-riscv64; cpu=rv64,zkne=true,zknd=true; prekey=0 ;;
  esac
  echo "LLVM AES conformance: $arch"
  "$cc" "${flags[@]}" -O2 -static -DPREKEY="$prekey" \
    ssa/testdata/aesllvm/check.c "$artifact_dir/$arch.o" -o "$artifact_dir/check-$arch"
  "$emulator" -cpu "$cpu" "$artifact_dir/check-$arch"
done
